<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Smart Crop AR Monitoring Interface</title>
<link href="https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&family=Sora:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap" rel="stylesheet">
<style>
  :root {
    --green-primary: #22c55e;
    --green-dark: #16a34a;
    --green-light: #86efac;
    --green-bg: #f0fdf4;
    --teal: #14b8a6;
    --amber: #f59e0b;
    --red: #ef4444;
    --purple: #8b5cf6;
    --blue: #3b82f6;
    --dark: #0f1a0f;
    --dark2: #1a2e1a;
    --card-bg: #ffffff;
    --card-border: #dcfce7;
    --text-primary: #0f172a;
    --text-muted: #64748b;
    --text-light: #94a3b8;
    --shadow: 0 4px 24px rgba(34,197,94,0.08);
    --shadow-lg: 0 8px 40px rgba(34,197,94,0.15);
    --sidebar-w: 240px;
    --header-h: 64px;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Sora', sans-serif;
    background: #f4faf5;
    color: var(--text-primary);
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* ─── HEADER ─── */
  header {
    position: fixed; top: 0; left: 0; right: 0; z-index: 100;
    height: var(--header-h);
    background: var(--dark);
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 24px;
    border-bottom: 1px solid rgba(34,197,94,0.2);
  }
  .header-left { display: flex; align-items: center; gap: 12px; }
  .logo-icon {
    width: 36px; height: 36px; border-radius: 10px;
    background: linear-gradient(135deg, var(--green-primary), var(--teal));
    display: flex; align-items: center; justify-content: center; font-size: 18px;
    box-shadow: 0 0 20px rgba(34,197,94,0.4);
  }
  .logo-text h1 { font-size: 16px; font-weight: 700; color: #fff; letter-spacing: -0.3px; }
  .logo-text p { font-size: 11px; color: rgba(255,255,255,0.5); margin-top: 1px; }
  .header-right { display: flex; align-items: center; gap: 16px; }
  .last-updated { text-align: right; }
  .last-updated span { display: block; font-size: 10px; color: rgba(255,255,255,0.4); font-family: 'JetBrains Mono', monospace; }
  .last-updated strong { font-size: 12px; color: rgba(255,255,255,0.85); font-family: 'JetBrains Mono', monospace; }
  .status-badge {
    display: flex; align-items: center; gap: 6px;
    background: rgba(34,197,94,0.12); border: 1px solid rgba(34,197,94,0.3);
    padding: 6px 14px; border-radius: 20px;
  }
  .status-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--green-primary); animation: pulse 2s infinite; }
  @keyframes pulse { 0%,100%{opacity:1;box-shadow:0 0 0 0 rgba(34,197,94,0.4)} 50%{opacity:0.8;box-shadow:0 0 0 6px rgba(34,197,94,0)} }
  .status-badge span { font-size: 12px; color: var(--green-light); font-weight: 500; }

  /* ─── LAYOUT ─── */
  .app-layout {
    display: grid;
    grid-template-columns: var(--sidebar-w) 1fr;
    grid-template-rows: auto;
    margin-top: var(--header-h);
    min-height: calc(100vh - var(--header-h));
  }

  /* ─── SIDEBAR ─── */
  aside {
    background: #fff;
    border-right: 1px solid var(--card-border);
    padding: 20px 0;
    position: sticky; top: var(--header-h);
    height: calc(100vh - var(--header-h));
    overflow-y: auto;
  }
  aside::-webkit-scrollbar { width: 4px; }
  aside::-webkit-scrollbar-thumb { background: var(--card-border); border-radius: 2px; }

  .sidebar-section { padding: 0 16px 16px; border-bottom: 1px solid var(--card-border); margin-bottom: 16px; }
  .sidebar-section:last-child { border-bottom: none; }
  .sidebar-title {
    font-size: 9px; letter-spacing: 1.5px; text-transform: uppercase;
    color: var(--text-light); font-weight: 600; margin-bottom: 12px;
    display: flex; align-items: center; gap: 6px;
  }
  .sidebar-title::before { content: ''; flex: 1; height: 1px; background: var(--card-border); }

  .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  .info-cell {
    background: var(--green-bg); border-radius: 10px; padding: 10px;
    border: 1px solid var(--card-border);
  }
  .info-cell label { font-size: 9px; color: var(--text-light); text-transform: uppercase; letter-spacing: 0.8px; display: block; margin-bottom: 4px; }
  .info-cell span { font-size: 13px; font-weight: 700; color: var(--text-primary); display: block; }
  .info-cell.full { grid-column: span 2; }
  .info-cell span.highlight { color: var(--green-dark); }

  .farmer-info { display: flex; flex-direction: column; gap: 10px; }
  .farmer-row { display: flex; align-items: center; gap: 10px; }
  .farmer-row .icon { width: 28px; height: 28px; border-radius: 8px; background: var(--green-bg); display: flex; align-items: center; justify-content: center; font-size: 13px; flex-shrink: 0; }
  .farmer-row .detail label { font-size: 9px; color: var(--text-light); display: block; }
  .farmer-row .detail span { font-size: 12px; font-weight: 600; }

  /* ─── HORIZONTAL CROP STAGE TIMELINE ─── */
  .timeline-card {
    background: var(--card-bg); border-radius: 16px;
    border: 1px solid var(--card-border);
    padding: 12px 20px; box-shadow: var(--shadow);
  }
  .stage-timeline { display: flex; flex-direction: row; gap: 0; overflow-x: auto; padding: 5px 0 10px; }
  .stage-timeline::-webkit-scrollbar { height: 6px; }
  .stage-timeline::-webkit-scrollbar-thumb { background: var(--card-border); border-radius: 3px; }
  .stage-item { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 0 5px; position: relative; cursor: pointer; flex: 1; min-width: 90px; }
  .stage-item::before {
    content: ''; position: absolute; top: 13px; left: 50%; right: -50%;
    height: 2px; width: 100%; background: var(--card-border); z-index: 0;
  }
  .stage-item:last-child::before { display: none; }
  .stage-dot {
    width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
    font-size: 11px; flex-shrink: 0; z-index: 1; position: relative; transition: transform 0.2s;
  }
  .stage-dot.done { background: var(--green-primary); color: white; }
  .stage-dot.active { background: var(--dark); color: var(--green-primary); border: 2px solid var(--green-primary); box-shadow: 0 0 12px rgba(34,197,94,0.4); animation: pulse 2s infinite; }
  .stage-dot.pending { background: var(--green-bg); color: var(--text-light); border: 2px solid var(--card-border); }
  .stage-item:hover .stage-dot { transform: scale(1.15); }
  .stage-name { font-size: 11px; font-weight: 500; color: var(--text-primary); transition: color 0.2s; text-align: center; }
  .stage-item.active .stage-name { color: var(--green-dark); font-weight: 700; }
  .stage-item.pending .stage-name { color: var(--text-light); }

  .stage-stats { display: flex; gap: 24px; padding: 0px 16px; margin-top: 4px; justify-content: center; }
  .stage-stat { text-align: center; }
  .stage-stat .num { font-size: 18px; font-weight: 800; font-family: 'Space Mono', monospace; }
  .stage-stat .lbl { font-size: 9px; color: var(--text-light); text-transform: uppercase; letter-spacing: 0.8px; }
  .stage-stat:nth-child(1) .num { color: var(--green-dark); }
  .stage-stat:nth-child(2) .num { color: var(--blue); }
  .stage-stat:nth-child(3) .num { color: var(--amber); }

  /* ─── MAIN CONTENT ─── */
  main { padding: 24px; display: flex; flex-direction: column; gap: 24px; overflow-y: auto; }

  /* ─── AR VIEWER ─── */
  .ar-viewer {
    border-radius: 20px; overflow: hidden; position: relative;
    min-height: 380px; box-shadow: 0 8px 48px rgba(0,0,0,0.5);
    border: 1px solid rgba(34,197,94,0.2);
    background: #071407;
  }

  /* ── REAL CROP FIELD PHOTO ── */
  .ar-photo-bg {
    position: absolute; inset: 0;
    /* Dense green crop field — sugarcane/paddy */
    background-image: url('data:image/webp;base64,');
    background-size: cover;
    background-position: center 65%;
    filter: brightness(0.46) saturate(1.25) hue-rotate(10deg) contrast(1.06);
    transform: scale(1.06);
    background-position: center 58%;
    animation: fieldBreath 16s ease-in-out infinite;
  }
  @keyframes fieldBreath {
    0%,100%{ transform:scale(1.05) translateY(0px) translateX(0px); }
    33%    { transform:scale(1.07) translateY(-5px) translateX(3px); }
    66%    { transform:scale(1.06) translateY(-2px) translateX(-3px); }
  }

  /* Green AR tint over the photo */
  .ar-color-overlay {
    position: absolute; inset: 0;
    background:
      linear-gradient(180deg,
        rgba(2,18,4,0.72) 0%,
        rgba(4,30,6,0.18) 28%,
        rgba(4,30,6,0.10) 55%,
        rgba(2,14,3,0.65) 100%),
      radial-gradient(ellipse at 50% 50%, rgba(34,197,94,0.07) 0%, transparent 65%);
  }

  /* AR scan grid lines — subtle */
  .ar-scanlines {
    position: absolute; inset: 0; pointer-events: none;
    background:
      repeating-linear-gradient(0deg,  transparent, transparent 34px, rgba(34,197,94,0.035) 34px, rgba(34,197,94,0.035) 35px),
      repeating-linear-gradient(90deg, transparent, transparent 48px, rgba(34,197,94,0.022) 48px, rgba(34,197,94,0.022) 49px);
    animation: scanMove 10s linear infinite;
  }
  @keyframes scanMove { from{background-position:0 0} to{background-position:0 35px} }

  /* Wind ripple overlay — makes photo field appear to sway */
  .ar-wind-ripple {
    position: absolute; inset: 0; pointer-events: none;
    background: linear-gradient(180deg,
      transparent 0%,
      transparent 45%,
      rgba(34,197,94,0.04) 55%,
      transparent 65%,
      rgba(34,197,94,0.03) 75%,
      transparent 85%
    );
    animation: windRipple 3.5s ease-in-out infinite;
  }
  @keyframes windRipple {
    0%  { transform: translateX(-2%) scaleX(1.04); opacity: 0.6; }
    50% { transform: translateX( 2%) scaleX(0.96); opacity: 1;   }
    100%{ transform: translateX(-2%) scaleX(1.04); opacity: 0.6; }
  }

  /* Horizon glow — light from sky reflecting on field */
  .ar-horizon {
    position: absolute; left: 0; right: 0;
    top: 38%; height: 60px;
    background: linear-gradient(180deg, rgba(34,197,94,0.07) 0%, transparent 100%);
    pointer-events: none;
  }

  /* Bottom ground line glow */
  .ar-ground-glow {
    position: absolute; bottom: 0; left: 0; right: 0; height: 6px;
    background: linear-gradient(90deg,
      transparent 0%,
      rgba(34,197,94,0.35) 20%,
      rgba(74,222,128,0.6) 50%,
      rgba(34,197,94,0.35) 80%,
      transparent 100%
    );
    filter: blur(4px);
  }

  /* Top bar */
  .ar-overlay-top {
    position: absolute; top: 0; left: 0; right: 0;
    display: flex; align-items: center;
    padding: 14px 20px; gap: 12px;
    background: linear-gradient(180deg, rgba(0,0,0,0.7) 0%, transparent 100%);
  }
  .ar-scan-bar { display: flex; align-items: center; gap: 10px; flex: 1; }
  .scan-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green-primary); animation: pulse 1.5s infinite; flex-shrink:0; }
  .scan-label { font-size: 12px; color: rgba(255,255,255,0.85); font-family: 'JetBrains Mono', monospace; letter-spacing: 0.5px; }
  .scan-progress { flex: 1; height: 3px; background: rgba(255,255,255,0.08); border-radius: 2px; overflow: hidden; margin-left: 6px; }
  .scan-fill { height: 100%; background: linear-gradient(90deg, var(--green-primary), var(--teal)); border-radius: 2px; animation: scanProgress 4s ease-in-out infinite; }
  @keyframes scanProgress { 0%{width:0} 80%{width:100%} 100%{width:100%} }
  .field-id-tag { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: rgba(255,255,255,0.45); letter-spacing: 1px; }

  /* Health score circle */
  .health-score-bubble {
    position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
    width: 140px; height: 140px; border-radius: 50%;
    background: rgba(5,20,5,0.82); backdrop-filter: blur(16px);
    border: 2px solid rgba(74,222,128,0.5);
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    box-shadow: 0 0 0 8px rgba(34,197,94,0.06), 0 0 50px rgba(34,197,94,0.35), inset 0 0 30px rgba(34,197,94,0.06);
    animation: breathe 4s ease-in-out infinite;
    z-index: 4;
  }
  @keyframes breathe {
    0%,100%{box-shadow:0 0 0 8px rgba(34,197,94,0.06),0 0 50px rgba(34,197,94,0.3)}
    50%{box-shadow:0 0 0 14px rgba(34,197,94,0.04),0 0 70px rgba(34,197,94,0.55)}
  }
  .health-score-bubble .leaf { font-size: 20px; margin-bottom: 2px; }
  .health-score-bubble .score { font-size: 38px; font-weight: 800; color: #4ade80; font-family: 'Space Mono', monospace; line-height: 1; }
  .health-score-bubble .hs-label { font-size: 9px; color: rgba(255,255,255,0.5); text-transform: uppercase; letter-spacing: 2px; margin-top: 4px; }

  /* Affected area tag */
  .affected-tag {
    position: absolute; left: 26%; top: 42%;
    background: rgba(120,30,20,0.7); backdrop-filter: blur(8px);
    border: 1px solid rgba(239,68,68,0.5); border-radius: 8px;
    padding: 5px 12px; font-size: 11px; color: #fca5a5; font-weight: 600;
    font-family: 'JetBrains Mono', monospace;
    animation: blink 2s ease-in-out infinite; z-index: 4;
    display: flex; align-items: center; gap: 5px;
  }
  @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0.6} }

  /* AR Tags right column */
  .ar-tags {
    position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
    display: flex; flex-direction: column; gap: 8px; z-index: 4;
  }
  .ar-tag {
    display: flex; align-items: center; gap: 10px;
    background: rgba(5,18,5,0.82); backdrop-filter: blur(12px);
    border: 1px solid rgba(255,255,255,0.09); border-radius: 12px; padding: 10px 14px;
    min-width: 185px; transition: transform 0.2s, background 0.2s;
    cursor: default;
  }
  .ar-tag:hover { transform: translateX(-4px); background: rgba(10,30,10,0.92); }
  .ar-tag .tag-icon {
    width: 32px; height: 32px; border-radius: 8px;
    display: flex; align-items: center; justify-content: center; font-size: 14px; flex-shrink: 0;
  }
  .ar-tag.amber .tag-icon { background: rgba(245,158,11,0.18); }
  .ar-tag.red .tag-icon { background: rgba(239,68,68,0.18); }
  .ar-tag.orange .tag-icon { background: rgba(234,88,12,0.18); }
  .ar-tag.purple .tag-icon { background: rgba(139,92,246,0.18); }
  .ar-tag .tag-info .tag-title { font-size: 13px; font-weight: 700; color: #fff; }
  .ar-tag .tag-info .tag-sub { font-size: 10px; color: rgba(255,255,255,0.4); margin-top: 2px; }

  /* Bottom stat tags */
  .ar-bottom-tags { position: absolute; bottom: 20px; left: 20px; display: flex; gap: 12px; z-index: 4; }
  .ar-bottom-tag {
    background: rgba(5,18,5,0.82); backdrop-filter: blur(12px);
    border: 1px solid rgba(255,255,255,0.09); border-radius: 14px; padding: 12px 18px;
    min-width: 140px;
  }
  .ar-bottom-tag .bt-label { font-size: 9px; color: rgba(255,255,255,0.38); text-transform: uppercase; letter-spacing: 1px; display: flex; align-items: center; gap: 4px; margin-bottom: 4px; }
  .ar-bottom-tag .bt-value { font-size: 22px; font-weight: 800; color: #fff; font-family: 'Space Mono', monospace; line-height: 1; }
  .ar-bottom-tag .bt-sub { font-size: 10px; color: var(--green-primary); margin-top: 3px; font-weight: 600; }

  /* ─── BOTTOM GRID ─── */
  .bottom-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }

  /* ─── CARDS ─── */
  .card {
    background: var(--card-bg); border-radius: 16px;
    border: 1px solid var(--card-border);
    padding: 20px; box-shadow: var(--shadow);
    transition: box-shadow 0.2s;
  }
  .card:hover { box-shadow: var(--shadow-lg); }
  .card-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }
  .card-title { font-size: 13px; font-weight: 700; color: var(--text-primary); display: flex; align-items: center; gap: 6px; }
  .card-title .card-icon { width: 26px; height: 26px; border-radius: 7px; background: var(--green-bg); display: flex; align-items: center; justify-content: center; font-size: 12px; }

  /* ─── HEALTH VITALS ─── */
  .vitals-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
  .vital-item label { font-size: 10px; color: var(--text-light); text-transform: uppercase; letter-spacing: 0.8px; display: block; margin-bottom: 4px; display: flex; justify-content: space-between; align-items: center; }
  .vital-item label span { font-size: 11px; font-weight: 600; color: var(--text-primary); text-transform: none; letter-spacing: 0; }
  .vital-value { font-size: 22px; font-weight: 800; font-family: 'Space Mono', monospace; color: var(--text-primary); }
  .vital-value.green { color: var(--green-dark); }
  .vital-value.amber { color: var(--amber); }
  .vital-value.red { color: var(--red); }
  .vital-bar { height: 4px; background: var(--green-bg); border-radius: 2px; margin-top: 4px; overflow: hidden; }
  .vital-fill { height: 100%; border-radius: 2px; }
  .vital-fill.green { background: linear-gradient(90deg, var(--green-primary), var(--teal)); }
  .vital-fill.amber { background: linear-gradient(90deg, var(--amber), #f97316); }
  .vital-fill.red { background: linear-gradient(90deg, var(--red), #dc2626); }
  .vital-fill.blue { background: linear-gradient(90deg, var(--blue), var(--teal)); }
  .vital-tag { font-size: 10px; font-weight: 600; margin-top: 3px; }
  .vital-tag.green { color: var(--green-dark); }
  .vital-tag.amber { color: var(--amber); }
  .vital-tag.red { color: var(--red); }

  .npk-bars { display: flex; gap: 8px; margin-top: 6px; }
  .npk-bar { flex: 1; text-align: center; }
  .npk-bar .npk-fill { height: 40px; border-radius: 4px; margin-bottom: 4px; position: relative; display: flex; align-items: flex-start; justify-content: center; padding-top: 3px; font-size: 9px; color: white; font-weight: 700; }
  .npk-bar.n .npk-fill { background: linear-gradient(180deg, #ef4444, #dc2626); height: 30px; }
  .npk-bar.p .npk-fill { background: linear-gradient(180deg, var(--green-primary), var(--green-dark)); height: 42px; }
  .npk-bar.k .npk-fill { background: linear-gradient(180deg, var(--green-primary), var(--green-dark)); height: 45px; }
  .npk-bar .npk-label { font-size: 10px; font-weight: 700; color: var(--text-muted); }
  .npk-bar .npk-status { font-size: 9px; color: var(--text-light); }

  .growth-stage-bar {
    margin-top: 14px; background: linear-gradient(135deg, var(--dark), var(--dark2));
    border-radius: 12px; padding: 14px;
  }
  .gsb-label { font-size: 9px; color: rgba(255,255,255,0.4); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 4px; }
  .gsb-title { font-size: 14px; font-weight: 700; color: #fff; margin-bottom: 10px; display: flex; align-items: center; justify-content: space-between; }
  .gsb-title span { font-size: 10px; color: var(--green-primary); }
  .gsb-progress { height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden; }
  .gsb-fill { height: 100%; background: linear-gradient(90deg, var(--green-primary), var(--teal)); border-radius: 3px; width: 67%; }

  /* ─── ACTIVITY LOG ─── */
  .activity-list { display: flex; flex-direction: column; gap: 10px; }
  .activity-item {
    display: flex; gap: 12px; padding: 12px; border-radius: 12px;
    background: var(--green-bg); border: 1px solid var(--card-border);
    transition: transform 0.2s, box-shadow 0.2s;
  }
  .activity-item:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
  .activity-dot { width: 34px; height: 34px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 14px; flex-shrink: 0; }
  .activity-dot.green { background: rgba(34,197,94,0.15); }
  .activity-dot.blue { background: rgba(59,130,246,0.15); }
  .activity-dot.amber { background: rgba(245,158,11,0.15); }
  .activity-dot.purple { background: rgba(139,92,246,0.15); }
  .activity-dot.teal { background: rgba(20,184,166,0.15); }
  .activity-content { flex: 1; min-width: 0; }
  .activity-header { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
  .activity-title { font-size: 12px; font-weight: 700; color: var(--text-primary); }
  .activity-badge { font-size: 9px; font-weight: 700; padding: 2px 7px; border-radius: 10px; flex-shrink: 0; }
  .activity-badge.applied { background: rgba(34,197,94,0.15); color: var(--green-dark); }
  .activity-badge.completed { background: rgba(59,130,246,0.15); color: var(--blue); }
  .activity-badge.recent { background: rgba(139,92,246,0.15); color: var(--purple); }
  .activity-sub { font-size: 10px; color: var(--text-muted); margin-top: 2px; }
  .activity-date { font-size: 9px; color: var(--text-light); margin-top: 4px; font-family: 'JetBrains Mono', monospace; display: flex; align-items: center; gap: 4px; }

  .supervisor-note {
    padding: 12px; background: linear-gradient(135deg, rgba(34,197,94,0.05), rgba(20,184,166,0.05));
    border: 1px solid rgba(34,197,94,0.15); border-radius: 12px;
    font-size: 11px; color: var(--text-muted); line-height: 1.5; font-style: italic;
    position: relative;
  }
  .supervisor-note::before { content: '"'; position: absolute; top: -4px; left: 10px; font-size: 30px; color: var(--green-primary); opacity: 0.3; font-style: normal; }
  .sup-name { font-size: 10px; color: var(--green-dark); font-weight: 600; margin-top: 6px; font-style: normal; }

  .img-uploads { display: flex; gap: 6px; margin-top: 8px; }
  .img-thumb { width: 40px; height: 40px; border-radius: 8px; border: 2px solid var(--card-border); display: flex; align-items: center; justify-content: center; font-size: 16px; cursor: pointer; transition: transform 0.2s; }
  .img-thumb:hover { transform: scale(1.1); }
  .img-thumb.green-t { background: linear-gradient(135deg, #22c55e, #16a34a); }
  .img-thumb.blue-t { background: linear-gradient(135deg, #3b82f6, #1d4ed8); }
  .img-thumb.add { background: var(--green-bg); font-size: 18px; color: var(--green-primary); }

  /* ─── YIELD & COST ─── */
  .yield-cost-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 12px; }
  .yield-block, .cost-block { }
  .yc-label { font-size: 9px; color: var(--text-light); text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 10px; display: flex; align-items: center; gap: 5px; }
  .yield-expected { font-size: 11px; color: var(--text-muted); margin-bottom: 4px; }
  .yield-expected span { font-weight: 700; color: var(--text-primary); }
  .yield-actual {
    background: linear-gradient(135deg, #dc2626, #b91c1c);
    border-radius: 10px; padding: 10px 12px;
    color: white;
  }
  .yield-actual .ya-value { font-size: 24px; font-weight: 800; font-family: 'Space Mono', monospace; }
  .yield-actual .ya-unit { font-size: 10px; opacity: 0.8; }
  .yield-actual .ya-sub { font-size: 10px; opacity: 0.7; margin-top: 2px; }
  .yield-prod { margin-top: 8px; font-size: 11px; color: var(--text-muted); }
  .yield-prod span { font-weight: 700; color: var(--text-primary); }
  .yield-target { color: var(--green-dark); font-size: 10px; font-weight: 600; margin-top: 3px; }

  .cost-items { display: flex; flex-direction: column; gap: 6px; }
  .cost-item { display: flex; justify-content: space-between; align-items: center; }
  .cost-item label { font-size: 10px; color: var(--text-muted); }
  .cost-item span { font-size: 11px; font-weight: 700; color: var(--text-primary); font-family: 'JetBrains Mono', monospace; }

  .total-invest {
    background: linear-gradient(135deg, var(--dark), #1e3a1e);
    border-radius: 10px; padding: 12px; margin-bottom: 10px;
    display: flex; justify-content: space-between; align-items: center;
  }
  .total-invest .ti-label { font-size: 10px; color: rgba(255,255,255,0.6); }
  .total-invest .ti-value { font-size: 18px; font-weight: 800; color: #fff; font-family: 'Space Mono', monospace; }
  .total-invest .ti-sub { font-size: 9px; color: rgba(255,255,255,0.4); margin-top: 2px; }

  .profit-block {
    background: linear-gradient(135deg, var(--green-primary), var(--green-dark));
    border-radius: 10px; padding: 12px;
    display: flex; justify-content: space-between; align-items: center;
  }
  .profit-block .pb-label { font-size: 10px; color: rgba(255,255,255,0.8); }
  .profit-block .pb-value { font-size: 20px; font-weight: 800; color: #fff; font-family: 'Space Mono', monospace; }
  .profit-block .pb-sub { font-size: 9px; color: rgba(255,255,255,0.7); margin-top: 2px; }

  /* Mini chart */
  .mini-chart { margin: 12px 0; }
  .mc-label { font-size: 9px; color: var(--text-light); margin-bottom: 6px; }
  .chart-svg { width: 100%; height: 50px; }

  .revenue-row { display: flex; gap: 8px; }
  .rev-item { flex: 1; text-align: center; background: var(--green-bg); border-radius: 8px; padding: 8px 4px; }
  .rev-item .rv-label { font-size: 8px; color: var(--text-light); text-transform: uppercase; letter-spacing: 0.5px; }
  .rev-item .rv-value { font-size: 11px; font-weight: 700; color: var(--green-dark); font-family: 'JetBrains Mono', monospace; margin-top: 2px; }
  .rev-item:nth-child(2) .rv-value { color: var(--red); }
  .rev-item:nth-child(3) .rv-value { color: var(--blue); }

  /* ─── RESPONSIVE ─── */
  @media (max-width: 1100px) {
    .bottom-grid { grid-template-columns: 1fr 1fr; }
    .bottom-grid > .card:last-child { grid-column: span 2; }
  }
  @media (max-width: 800px) {
    :root { --sidebar-w: 0px; }
    .app-layout { grid-template-columns: 1fr; }
    aside { display: none; }
    .bottom-grid { grid-template-columns: 1fr; }
    .bottom-grid > .card:last-child { grid-column: span 1; }
    main { padding: 16px; }
    .vitals-grid { grid-template-columns: 1fr; }
    .yield-cost-grid { grid-template-columns: 1fr; }
    .ar-tags { display: none; }
    .mobile-menu-btn { display: flex; }
  }
  @media (max-width: 500px) {
    .header-left .logo-text p { display: none; }
    .last-updated { display: none; }
  }

  /* ─── MOBILE SIDEBAR TOGGLE ─── */
  .mobile-menu-btn {
    display: none; background: none; border: none;
    color: white; font-size: 20px; cursor: pointer;
    margin-right: 8px;
  }
  .mobile-overlay {
    display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.5);
    z-index: 90; backdrop-filter: blur(2px);
  }
  .mobile-overlay.active { display: block; }
  @media (max-width: 800px) {
    .mobile-menu-btn { display: flex; }
    aside {
      display: flex; flex-direction: column;
      position: fixed; left: -260px; top: var(--header-h); bottom: 0;
      width: 260px; z-index: 95; transition: left 0.3s ease;
    }
    aside.open { left: 0; }
  }

  /* Scrollbar */
  main::-webkit-scrollbar { width: 4px; }
  main::-webkit-scrollbar-thumb { background: var(--card-border); border-radius: 2px; }

  /* Fade in animation */
  .fade-in { animation: fadeInUp 0.5s ease forwards; opacity: 0; }
  @keyframes fadeInUp { from{opacity:0;transform:translateY(16px)} to{opacity:1;transform:translateY(0)} }
  .delay-1 { animation-delay: 0.1s; }
  .delay-2 { animation-delay: 0.2s; }
  .delay-3 { animation-delay: 0.3s; }
  .delay-4 { animation-delay: 0.4s; }
</style>
</head>
<body>

<!-- HEADER -->
<header>
  <div class="header-left">
    <button class="mobile-menu-btn" onclick="toggleSidebar()" aria-label="Toggle menu">☰</button>
    <div class="logo-icon">🌿</div>
    <div class="logo-text">
      <h1>Smart Crop AR</h1>
      <p>Real-time AI-powered Crop Health &amp; Lifecycle Management</p>
    </div>
  </div>
  <div class="header-right">
    <div class="last-updated">
      <span>Last Updated</span>
      <strong id="currentDate">Feb 24, 2026 · 09:45 AM</strong>
    </div>
    <div class="status-badge">
      <span class="status-dot"></span>
      <span>System Active</span>
    </div>
  </div>
</header>

<div class="mobile-overlay" id="mobileOverlay" onclick="toggleSidebar()"></div>

<!-- APP LAYOUT -->
<div class="app-layout">

  <!-- SIDEBAR -->
  <aside id="sidebar">

    <!-- CROP INFORMATION -->
    <div class="sidebar-section">
      <div class="sidebar-title">🌾 Crop Information</div>
      <div class="info-grid">
        <div class="info-cell">
          <label>Crop Name</label>
          <span class="highlight">Sugarcane</span>
        </div>
        <div class="info-cell">
          <label>Field ID</label>
          <span>CRP-2026-447</span>
        </div>
        <div class="info-cell">
          <label>Season</label>
          <span>Rabi</span>
        </div>
        <div class="info-cell">
          <label>Total Area</label>
          <span>12.5 Acres</span>
        </div>
      </div>
      <div class="farmer-info" style="margin-top:12px;">
        <div class="farmer-row">
          <div class="icon">👨‍🌾</div>
          <div class="detail">
            <label>Farmer Name</label>
            <span>Ramesh Kumar</span>
          </div>
        </div>
        <div class="farmer-row">
          <div class="icon">📍</div>
          <div class="detail">
            <label>Location</label>
            <span>Nashik, Maharashtra</span>
          </div>
        </div>
      </div>
    </div>

    <!-- IDENTIFICATION -->
    <div class="sidebar-section">
      <div class="sidebar-title">🔍 Identification</div>
      <div class="info-grid">
        <div class="info-cell">
          <label>Field ID</label>
          <span>CRP-2026-447</span>
        </div>
        <div class="info-cell">
          <label>Geo Tag</label>
          <span>19.99°N 73.78°E</span>
        </div>
        <div class="info-cell">
          <label>Soil Type</label>
          <span>Black Cotton</span>
        </div>
        <div class="info-cell">
          <label>Irrigation</label>
          <span>Drip</span>
        </div>
        <div class="info-cell full">
          <label>Crop Variety</label>
          <span class="highlight">Co 86032</span>
        </div>
      </div>
    </div>



  </aside>

  <!-- MAIN -->
  <main>

    <!-- AR VIEWER -->
    <div class="ar-viewer fade-in">

      <!-- Real crop field photo background -->
      <div class="ar-photo-bg"></div>
      <!-- Dark green tint -->
      <div class="ar-color-overlay"></div>
      <!-- Scan grid lines -->
      <div class="ar-scanlines"></div>

      <!-- Wind ripple + horizon glow on top of real photo -->
      <div class="ar-wind-ripple"></div>
      <div class="ar-horizon"></div>
      <div class="ar-ground-glow"></div>

      <!-- Top scan bar -->
      <div class="ar-overlay-top">
        <div class="ar-scan-bar">
          <span class="scan-dot"></span>
          <span class="scan-label">Scanning Crop ...</span>
          <div class="scan-progress"><div class="scan-fill"></div></div>
        </div>
        <span class="field-id-tag">Field: CRP-2026-447</span>
      </div>

      <!-- Health score center -->
      <div class="health-score-bubble">
        <span class="leaf">🌿</span>
        <span class="score">84%</span>
        <span class="hs-label">Health Score</span>
      </div>

      <!-- Affected Area tag -->
      <div class="affected-tag">⚠ Affected Area</div>

      <!-- AR Info Tags — right -->
      <div class="ar-tags">
        <div class="ar-tag amber">
          <div class="tag-icon">🦗</div>
          <div class="tag-info">
            <div class="tag-title">12% Aphids</div>
            <div class="tag-sub">Low Risk</div>
          </div>
        </div>
        <div class="ar-tag red">
          <div class="tag-icon">🍂</div>
          <div class="tag-info">
            <div class="tag-title">Leaf Blight 5%</div>
            <div class="tag-sub">Monitor Closely</div>
          </div>
        </div>
        <div class="ar-tag orange">
          <div class="tag-icon">🪣</div>
          <div class="tag-info">
            <div class="tag-title">Slightly Low N</div>
            <div class="tag-sub">Fertilizer Needed</div>
          </div>
        </div>
        <div class="ar-tag purple">
          <div class="tag-icon">🌤️</div>
          <div class="tag-info">
            <div class="tag-title">Weather Low Risk</div>
            <div class="tag-sub">Clear Skies</div>
          </div>
        </div>
      </div>

      <!-- Bottom stat tags -->
      <div class="ar-bottom-tags">
        <div class="ar-bottom-tag">
          <div class="bt-label">💧 Soil Moisture</div>
          <div class="bt-value">62%</div>
          <div class="bt-sub">Optimal</div>
        </div>
        <div class="ar-bottom-tag">
          <div class="bt-label">🚿 Irrigation Stress</div>
          <div class="bt-value">Normal</div>
          <div class="bt-sub">Healthy</div>
        </div>
      </div>
    </div>

    <!-- CROP STAGE TIMELINE CARD -->
    <div class="card timeline-card fade-in delay-1">
      <div class="card-header" style="margin-bottom:0;">
        <div class="card-title">
          <div class="card-icon">📅</div>
          Crop Stage Timeline
        </div>
      </div>
      <div class="stage-timeline" id="stageTimeline"></div>
      <div class="stage-stats">
        <div class="stage-stat">
          <div class="num">9</div>
          <div class="lbl">Done</div>
        </div>
        <div class="stage-stat">
          <div class="num">1</div>
          <div class="lbl">Active</div>
        </div>
        <div class="stage-stat">
          <div class="num">5</div>
          <div class="lbl">Pending</div>
        </div>
      </div>
    </div>

    <!-- BOTTOM GRID -->
    <div class="bottom-grid">

      <!-- CROP HEALTH VITALS -->
      <div class="card fade-in delay-1">
        <div class="card-header">
          <div class="card-title">
            <div class="card-icon">💊</div>
            Crop Health Vitals
          </div>
          <span style="font-size:10px;color:var(--green-primary);font-weight:600;">Live ●</span>
        </div>
        <div class="vitals-grid">
          <div class="vital-item">
            <label>NDVI Index <span style="color:var(--green-primary)">🌿</span></label>
            <div class="vital-value green">0.68</div>
            <div class="vital-bar"><div class="vital-fill green" style="width:68%"></div></div>
            <div class="vital-tag green">Healthy Vegetation</div>
          </div>
          <div class="vital-item">
            <label>Soil Moisture <span>💧</span></label>
            <div class="vital-value" style="color:var(--blue)">62%</div>
            <div class="vital-bar"><div class="vital-fill blue" style="width:62%"></div></div>
            <div class="vital-tag" style="color:var(--blue)">Optimal Level</div>
          </div>
          <div class="vital-item">
            <label>NPK Levels <span>🧪</span></label>
            <div class="npk-bars">
              <div class="npk-bar n">
                <div class="npk-fill">N</div>
                <div class="npk-label">N</div>
                <div class="npk-status" style="color:var(--red)">Low</div>
              </div>
              <div class="npk-bar p">
                <div class="npk-fill">P</div>
                <div class="npk-label">P</div>
                <div class="npk-status" style="color:var(--green-dark)">Good</div>
              </div>
              <div class="npk-bar k">
                <div class="npk-fill">K</div>
                <div class="npk-label">K</div>
                <div class="npk-status" style="color:var(--green-dark)">Good</div>
              </div>
            </div>
            <div class="vital-tag amber" style="margin-top:6px;">⚠ Nitrogen Needed</div>
          </div>
          <div class="vital-item">
            <label>Pest Severity <span>🦟</span></label>
            <div class="vital-value amber">12%</div>
            <div class="vital-bar"><div class="vital-fill amber" style="width:12%"></div></div>
            <div class="vital-tag amber">Low Risk</div>
          </div>
          <div class="vital-item">
            <label>Disease Prob. <span>🔴</span></label>
            <div class="vital-value red">5%</div>
            <div class="vital-bar"><div class="vital-fill red" style="width:5%"></div></div>
            <div class="vital-tag red">Leaf Blight Detected</div>
          </div>
          <div class="vital-item">
            <label>Water Stress <span>🌊</span></label>
            <div class="vital-value">0.32</div>
            <div class="vital-bar"><div class="vital-fill blue" style="width:32%"></div></div>
            <div class="vital-tag" style="color:var(--text-muted)">Normal</div>
          </div>
        </div>
        <div class="growth-stage-bar">
          <div class="gsb-label">Current Growth Stage</div>
          <div class="gsb-title">Activity Monitoring <span>67% Complete →</span></div>
          <div class="gsb-progress"><div class="gsb-fill"></div></div>
        </div>
      </div>

      <!-- ACTIVITY MONITORING LOG -->
      <div class="card fade-in delay-2">
        <div class="card-header">
          <div class="card-title">
            <div class="card-icon">👁</div>
            Activity Monitoring Log
          </div>
        </div>
        <div class="activity-list">
          <div class="activity-item">
            <div class="activity-dot green">🌱</div>
            <div class="activity-content">
              <div class="activity-header">
                <span class="activity-title">Last Fertilizer Application</span>
                <span class="activity-badge applied">Applied</span>
              </div>
              <div class="activity-sub">Urea (46-0-0) · Qty: 50 kg/acre</div>
              <div class="activity-date">📅 Feb 18, 2026 · Next Due: Mar 10, 2026</div>
            </div>
          </div>
          <div class="activity-item">
            <div class="activity-dot blue">💧</div>
            <div class="activity-content">
              <div class="activity-header">
                <span class="activity-title">Last Irrigation</span>
                <span class="activity-badge completed">Completed</span>
              </div>
              <div class="activity-sub">Drip Irrigation · 4 hours</div>
              <div class="activity-date">📅 Feb 22, 2026 · Next: Feb 25, 2026</div>
            </div>
          </div>
          <div class="activity-item">
            <div class="activity-dot amber">🧴</div>
            <div class="activity-content">
              <div class="activity-header">
                <span class="activity-title">Pesticide Spray</span>
                <span class="activity-badge applied">Applied</span>
              </div>
              <div class="activity-sub">Chlorpyrifos 20% EC · Dosage: 2.5 ml/L</div>
              <div class="activity-date">📅 Feb 15, 2026 · Target: Aphids</div>
            </div>
          </div>
          <div class="activity-item">
            <div class="activity-dot purple">📋</div>
            <div class="activity-content">
              <div class="activity-header">
                <span class="activity-title">Field Visit</span>
                <span class="activity-badge recent">Recent</span>
              </div>
              <div class="activity-sub">Regular Inspection</div>
              <div class="activity-date">📅 Feb 23, 2026</div>
            </div>
          </div>
          <div class="supervisor-note">
            Crop health is excellent. Minor aphid infestation detected in sector B. Applied organic pesticide. Nitrogen levels slightly low — recommend urea application within 7 days. Irrigation schedule is adequate.
            <div class="sup-name">— Dr. Suresh Patil, Agricultural Officer</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-muted);margin-bottom:6px;">📷 Image Proof Upload · 3 images attached</div>
            <div class="img-uploads">
              <div class="img-thumb green-t">🌿</div>
              <div class="img-thumb blue-t">💊</div>
              <div class="img-thumb add">+</div>
            </div>
          </div>
        </div>
      </div>


      <!-- YIELD & COST SUMMARY -->
      <div class="card fade-in delay-3">
        <div class="card-header">
          <div class="card-title">
            <div class="card-icon">📊</div>
            Yield &amp; Cost Summary
          </div>
        </div>
        <div class="yield-cost-grid">
          <div class="yield-block">
            <div class="yc-label">🌾 Yield Summary</div>
            <div class="yield-expected">Expected: <span>95 Tons</span></div>
            <div class="yield-expected" style="font-size:9px;color:var(--text-light);">7.6 tons/acre</div>
            <div class="yield-actual" style="margin-top:8px;">
              <div class="ya-unit">Actual Yield (Projected)</div>
              <div class="ya-value">98 T</div>
              <div class="ya-sub">29.8 tons/acre</div>
            </div>
            <div class="yield-prod" style="margin-top:8px;">Production/Acre: <span>78.4</span></div>
            <div class="yield-target">📈 +3.2% above target</div>
          </div>
          <div class="cost-block">
            <div class="yc-label">💰 Cost Summary</div>
            <div class="cost-items">
              <div class="cost-item">
                <label>Land Prep</label>
                <span>₹18,500</span>
              </div>
              <div class="cost-item">
                <label>Fertilizer</label>
                <span>₹32,400</span>
              </div>
              <div class="cost-item">
                <label>Irrigation</label>
                <span>₹15,800</span>
              </div>
              <div class="cost-item">
                <label>Labour</label>
                <span>₹45,000</span>
              </div>
              <div class="cost-item">
                <label>Crop Protect.</label>
                <span>₹12,300</span>
              </div>
            </div>
          </div>
        </div>

        <div class="total-invest">
          <div>
            <div class="ti-label">Total Investment</div>
            <div class="ti-sub">₹9,920 per acre</div>
          </div>
          <div class="ti-value">₹1,24,000</div>
        </div>

        <div class="mini-chart">
          <div class="mc-label">Yield Growth Trend</div>
          <svg class="chart-svg" viewBox="0 0 200 50" preserveAspectRatio="none">
            <defs>
              <linearGradient id="chartGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stop-color="#22c55e" stop-opacity="0.3"/>
                <stop offset="100%" stop-color="#22c55e" stop-opacity="0"/>
              </linearGradient>
            </defs>
            <path d="M0,45 L30,40 L60,35 L90,30 L120,22 L150,18 L180,12 L200,8" fill="none" stroke="#22c55e" stroke-width="2" stroke-linecap="round"/>
            <path d="M0,45 L30,40 L60,35 L90,30 L120,22 L150,18 L180,12 L200,8 L200,50 L0,50 Z" fill="url(#chartGrad)"/>
            <circle cx="200" cy="8" r="4" fill="#22c55e"/>
          </svg>
        </div>

        <div class="profit-block">
          <div>
            <div class="pb-label">Estimated Profit</div>
            <div class="pb-sub">ROI: 237%</div>
          </div>
          <div class="pb-value">₹2,94,000</div>
        </div>

        <div class="revenue-row" style="margin-top:10px;">
          <div class="rev-item">
            <div class="rv-label">Revenue (Est.)</div>
            <div class="rv-value">₹4,18,000</div>
          </div>
          <div class="rev-item">
            <div class="rv-label">Cost/Ton</div>
            <div class="rv-value">₹1,265</div>
          </div>
          <div class="rev-item">
            <div class="rv-label">Break-Even</div>
            <div class="rv-value" style="color:var(--blue)">30 Tons</div>
          </div>
        </div>
      </div>

    </div>
  </main>
</div>

<script>
  // ── Sidebar Toggle (mobile) ──
  function toggleSidebar() {
    const sidebar = document.getElementById('sidebar');
    const overlay = document.getElementById('mobileOverlay');
    sidebar.classList.toggle('open');
    overlay.classList.toggle('active');
  }

  // ── Stage Timeline ──
  const stages = [
    { name: 'Area Leveling', status: 'done' },
    { name: 'Pre Field Preparation', status: 'done' },
    { name: 'Pre Irrigation', status: 'done' },
    { name: 'Land Preparation', status: 'done' },
    { name: 'Sowing', status: 'done' },
    { name: 'Post Irrigation', status: 'done' },
    { name: 'Fertilizers', status: 'done' },
    { name: 'Inter Culture', status: 'done' },
    { name: 'Crop Protection', status: 'done' },
    { name: 'Activity Monitoring', status: 'active' },
    { name: 'Harvest', status: 'pending' },
    { name: 'Hay Making', status: 'pending' },
    { name: 'Silage Making', status: 'pending' },
    { name: 'Yield Production Summary', status: 'pending' },
    { name: 'Cost Analysis', status: 'pending' },
  ];

  const timeline = document.getElementById('stageTimeline');
  stages.forEach(s => {
    const icons = { done: '✓', active: '◉', pending: '○' };
    const item = document.createElement('div');
    item.className = `stage-item ${s.status}`;
    item.innerHTML = `
      <div class="stage-dot ${s.status}">${icons[s.status]}</div>
      <span class="stage-name">${s.name}</span>
    `;
    timeline.appendChild(item);
  });

  // ── AR Crop: embedded base64 photo ──

  // ── Live Clock ──
  function updateClock() {
    const now = new Date();
    const opts = { month: 'short', day: 'numeric', year: 'numeric' };
    const date = now.toLocaleDateString('en-IN', opts);
    const time = now.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
    document.getElementById('currentDate').textContent = `${date} · ${time}`;
  }
  updateClock();
  setInterval(updateClock, 60000);

  // ── Animate vitals bars on load ──
  window.addEventListener('load', () => {
    document.querySelectorAll('.vital-fill, .gsb-fill').forEach(el => {
      const target = el.style.width;
      el.style.width = '0%';
      setTimeout(() => {
        el.style.transition = 'width 1s ease';
        el.style.width = target;
      }, 300);
    });
  });
</script>
</body>
</html>